package main

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/corentings/chess/v2"
)

// Released scoring, retained as an independent placement/material control.
func releasedStaticScore(position *chess.Position, perspective chess.Color) int {
	board := position.Board()
	phase := 0
	for square := chess.A1; square <= chess.H8; square++ {
		phase += phaseWeight(board.Piece(square).Type())
	}
	phase = min(24, phase)
	score := 0
	for square := chess.A1; square <= chess.H8; square++ {
		piece := board.Piece(square)
		if piece == chess.NoPiece {
			continue
		}
		rank := int(square) / 8
		if piece.Color() == chess.Black {
			rank = 7 - rank
		}
		value := pieceValues[piece.Type()] + placement(piece.Type(), int(square)%8, rank, phase)
		if piece.Color() == perspective {
			score += value
		} else {
			score -= value
		}
	}
	return score
}

func TestPositionalBaselineAndBreakdown(t *testing.T) {
	data, err := os.ReadFile("testdata/positional-validation.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Cases []struct {
			FEN string `json:"fen"`
		} `json:"cases"`
	}
	if err = json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	for _, c := range fixture.Cases {
		position := evalFEN(t, c.FEN)
		before := position.String()
		for _, side := range []chess.Color{chess.White, chess.Black} {
			base := positionalEvaluation(position, side, 0)
			if base.total() != releasedStaticScore(position, side) {
				t.Fatal("disabled features changed released score", c.FEN)
			}
			all := positionalEvaluation(position, side, candidateFeatures)
			if all.material != materialScore(position, side) || all.total() != staticScore(position, side) {
				t.Fatal("score contract changed")
			}
			for _, feature := range []positionalFeatures{pawnStructure, kingShelter, minorActivity} {
				part := positionalEvaluation(position, side, feature)
				if part.total()-base.total() != allFeatureContribution(all, feature) {
					t.Fatal("feature ablation inconsistent")
				}
			}
		}
		if position.String() != before {
			t.Fatal("evaluation changed root")
		}
	}
}
func allFeatureContribution(terms evaluationTerms, feature positionalFeatures) int {
	switch feature {
	case pawnStructure:
		return terms.pawns
	case kingShelter:
		return terms.shelter
	case minorActivity:
		return terms.activity
	}
	return 0
}

func TestPawnStructureDefinitions(t *testing.T) {
	for _, tt := range []struct {
		name, fen      string
		middle, ending int
	}{
		{"doubled with adjacent support", "4k3/2p5/8/8/8/2P5/1PP5/4K3 w - - 0 1", -12, -18},
		{"doubled isolated edge", "4k3/p7/8/8/8/P7/P7/4K3 w - - 0 1", -32, -42},
		{"advanced passer", "4k3/7p/P7/8/8/8/8/4K3 w - - 0 1", 40, 88},
		{"blocked passer", "4k3/n6p/P7/8/8/8/8/4K3 w - - 0 1", 15, 38},
		{"adjacent pawn ahead stops passer", "4k3/1p6/P7/8/8/8/8/4K3 w - - 0 1", -10, -12},
		{"adjacent pawn behind does not", "4k3/8/P7/1p6/8/8/8/4K3 w - - 0 1", 40, 88},
		{"rear passer not double credited", "4k3/7p/P7/8/8/P7/8/4K3 w - - 0 1", 18, 58},
	} {
		t.Run(tt.name, func(t *testing.T) {
			p := evalFEN(t, tt.fen)
			board := summarizeBoard(p)
			m, e := board.pawnScore(chess.White)
			if m != tt.middle || e != tt.ending {
				t.Fatalf("pawn terms %d/%d want %d/%d", m, e, tt.middle, tt.ending)
			}
			mirror := summarizeBoard(evalFEN(t, mirrorPositionalFEN(t, tt.fen)))
			bm, be := mirror.pawnScore(chess.Black)
			if bm != m || be != e {
				t.Fatal("black forward direction differs")
			}
		})
	}
}

func TestRealKingShelterAndPhase(t *testing.T) {
	shield := summarizeBoard(evalFEN(t, "r3k3/8/8/8/8/8/5PPP/6K1 w - - 0 1"))
	exposed := summarizeBoard(evalFEN(t, "r3k3/8/8/8/8/8/PPP5/6K1 w - - 0 1"))
	if shield.shelterScore(chess.White) != 42 || exposed.shelterScore(chess.White) != -60 {
		t.Fatal("actual pawns/open files not reflected")
	}
	near := summarizeBoard(evalFEN(t, "r3k3/8/8/8/8/5PPP/8/6K1 w - - 0 1"))
	if near.shelterScore(chess.White) != 21 {
		t.Fatal("second rank shield should receive half credit")
	}
	bare := positionalEvaluation(evalFEN(t, "4k3/8/8/8/8/8/5PPP/6K1 w - - 0 1"), chess.White, candidateFeatures)
	if bare.phase != 0 || bare.shelter != 0 {
		t.Fatal("shelter persisted into pawn-only ending")
	}
	for phase := 0; phase <= 24; phase++ {
		got := tapered(42, 0, phase)
		if got < 0 || got > 42 {
			t.Fatal("phase blend outside endpoints")
		}
	}
}

func TestMinorMobilityOccupancyAndPawnAttacks(t *testing.T) {
	for _, tt := range []struct {
		fen    string
		square chess.Square
		want   int
	}{
		{"7k/8/8/8/3N4/8/8/K7 w - - 0 1", chess.D4, 8},
		{"7k/8/4p3/8/3N4/8/2P5/K7 w - - 0 1", chess.D4, 6},
		{"8/7k/8/8/3B4/8/K7/8 w - - 0 1", chess.D4, 13},
		{"8/7k/8/2P1P3/3B4/2P1P3/K7/8 w - - 0 1", chess.D4, 0},
	} {
		p := evalFEN(t, tt.fen)
		board := summarizeBoard(p)
		if got := board.mobility(int(tt.square)); got != tt.want {
			t.Fatalf("mobility %d want%d in %s", got, tt.want, tt.fen)
		}
		// Independent library attack map, filtered using the declared feature.
		side := p.Board().Piece(tt.square).Color()
		unsafe := map[chess.Square]bool{}
		for square, piece := range p.Board().SquareMap() {
			if piece.Color() == side.Other() && piece.Type() == chess.Pawn {
				for _, target := range p.Board().AttacksFrom(square) {
					unsafe[target] = true
				}
			}
		}
		oracle := 0
		for _, target := range p.Board().AttacksFrom(tt.square) {
			if p.Board().Piece(target).Color() != side && !unsafe[target] {
				oracle++
			}
		}
		if oracle != tt.want {
			t.Fatal("hand-counted mobility disagrees with independent attacks")
		}
	}
}

func mirrorPositionalFEN(t *testing.T, fen string) string {
	t.Helper()
	fields := strings.Fields(fen)
	if fields[2] != "-" || fields[3] != "-" {
		t.Fatal("mirror fixture helper expects no castling or ep")
	}
	ranks := strings.Split(fields[0], "/")
	for i, j := 0, 7; i < j; i, j = i+1, j-1 {
		ranks[i], ranks[j] = ranks[j], ranks[i]
	}
	fields[0] = strings.Map(func(r rune) rune {
		if r >= 'a' && r <= 'z' {
			return r - 32
		}
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
		return r
	}, strings.Join(ranks, "/"))
	if fields[1] == "w" {
		fields[1] = "b"
	} else {
		fields[1] = "w"
	}
	return strings.Join(fields, " ")
}

func TestBoardAwareSymmetryAndTerminalDominance(t *testing.T) {
	for _, fen := range []string{
		"4k3/pp4pp/2p5/3N4/3P4/2B5/PP4PP/4K3 w - - 0 1",
		"r2qk2r/ppp2ppp/8/8/8/8/PPP2PPP/R2Q2KR w - - 0 1",
		"4k3/7p/P7/8/8/8/8/4K3 w - - 0 1",
	} {
		p := evalFEN(t, fen)
		mirror := evalFEN(t, mirrorPositionalFEN(t, fen))
		a, b := positionalEvaluation(p, chess.White, candidateFeatures), positionalEvaluation(mirror, chess.Black, candidateFeatures)
		if a != b || staticScore(p, chess.White) != -staticScore(p, chess.Black) {
			t.Fatal("color/rank or perspective symmetry failed", a, b)
		}
	}
	promotionHeavy := evalFEN(t, "QQQ1kQQQ/QQQQQQQQ/8/8/8/8/QQQQQQQQ/QQQ1KQQQ w - - 0 1")
	if summarizeBoard(promotionHeavy).phase != 24 || abs(staticScore(promotionHeavy, chess.White)) >= mateScore {
		t.Fatal("phase cap or mate dominance failed")
	}
	if evaluate(evalFEN(t, "7k/6Q1/5K2/8/8/8/8/8 b - - 0 1"), chess.Black) != -mateScore {
		t.Fatal("mate overridden")
	}
	if evaluate(evalFEN(t, "7k/5K2/6Q1/8/8/8/8/8 b - - 0 1"), chess.Black) != 0 {
		t.Fatal("stalemate overridden")
	}
}

func TestEnPassantQuiescenceIncludesPassedPawnValue(t *testing.T) {
	for _, tt := range []struct{ fen, move string }{
		{"k7/8/8/3pP3/8/8/8/7K w - d6 0 1", "e5d6"},
		{"7k/8/8/8/3Pp3/8/8/K7 b - d3 0 1", "e4d3"},
	} {
		p := evalFEN(t, tt.fen)
		move := killerTestMove(t, p, tt.move)
		child := p.Update(&move)
		want := evaluate(child, p.Turn())
		got := quiescence(p, quiescenceDepth, -searchInfinity, searchInfinity)
		if materialScore(child, p.Turn()) != 100 || got != want || got <= 100 {
			t.Fatalf("EP score%d want positional leaf%d, material100", got, want)
		}
	}
}

func TestEvaluationAllocations(t *testing.T) {
	p := evalFEN(t, timeoutPosition)
	if n := testing.AllocsPerRun(100, func() { _ = staticScore(p, chess.White) }); n != 0 {
		t.Fatalf("evaluation allocates: %g", n)
	}
}

func BenchmarkPositionFeatures(b *testing.B) {
	for _, tt := range []struct{ name, fen string }{{"start", chess.StartingPosition().String()}, {"dense", timeoutPosition}, {"crowded", crowdedPosition}} {
		g, err := parsePosition(strings.Fields("fen " + tt.fen))
		if err != nil {
			b.Fatal(err)
		}
		p := g.Position()
		b.Run(tt.name+"/released", func(b *testing.B) {
			b.ReportAllocs()
			for range b.N {
				_ = releasedStaticScore(p, chess.White)
			}
		})
		b.Run(tt.name+"/pawn-king", func(b *testing.B) {
			b.ReportAllocs()
			for range b.N {
				_ = positionalEvaluation(p, chess.White, pawnStructure|kingShelter).total()
			}
		})
		b.Run(tt.name+"/candidate", func(b *testing.B) {
			b.ReportAllocs()
			for range b.N {
				_ = staticScore(p, chess.White)
			}
		})
	}
}

func TestPawnAttackMasksMatchLibrary(t *testing.T) {
	for _, fen := range []string{chess.StartingPosition().String(), "7k/p6p/8/8/8/8/P6P/K7 w - - 0 1"} {
		p := evalFEN(t, fen)
		board := summarizeBoard(p)
		for _, side := range []chess.Color{chess.White, chess.Black} {
			var want uint64
			for square, piece := range p.Board().SquareMap() {
				if piece.Color() == side && piece.Type() == chess.Pawn {
					for _, target := range p.Board().AttacksFrom(square) {
						want |= uint64(1) << target
					}
				}
			}
			if board.pawnAttacks[side] != want {
				t.Fatalf("pawn attack wrap/direction mismatch for %v", side)
			}
		}
	}
}

